import{_ as i,o as t,c as a,a2 as l}from"./chunks/framework.1lnE8eph.js";const p=JSON.parse('{"title":"Bus Map: Consolidated Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"specs/001-init.md","filePath":"specs/001-init.md"}'),n={name:"specs/001-init.md"};function o(s,e,r,d,c,u){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="bus-map-consolidated-requirements" tabindex="-1">Bus Map: Consolidated Requirements <a class="header-anchor" href="#bus-map-consolidated-requirements" aria-label="Permalink to &quot;Bus Map: Consolidated Requirements&quot;">​</a></h1><h2 id="_1-scope" tabindex="-1">1. Scope <a class="header-anchor" href="#_1-scope" aria-label="Permalink to &quot;1. Scope&quot;">​</a></h2><p>Build a modular transit-operations dashboard from the Lego DnD application starterkit, with a live bus schedule, Gantt timelines, geographic routes, and a reusable design system.</p><p>This specification defines the final requirements consolidated from both sessions.</p><h2 id="_2-project-setup-and-tooling" tabindex="-1">2. Project setup and tooling <a class="header-anchor" href="#_2-project-setup-and-tooling" aria-label="Permalink to &quot;2. Project setup and tooling&quot;">​</a></h2><ul><li>Extract the supplied ZIP archives for the starterkit, architecture guidance, knowledge, graphs, and map.</li><li>Copy <code>lego-application-starterkit-dnd-main</code> into a new <code>app</code> directory.</li><li>Replace the <code>@starterkit</code> workspace scope with <code>@busmap</code>.</li><li>Verify installation, development startup, and production builds using Yarn.</li><li>Install required private Lego packages using the supplied registry configuration without copying credentials into source control.</li><li>Use TanStack Table v9, Lego Graphs Gantt, and Lego OpenLayers.</li><li>Upgrade React, TypeScript, Vite, and esbuild to their latest stable versions at the time of the upgrade.</li><li>Preserve existing behavior and resolve upgrade incompatibilities.</li></ul><h2 id="_3-application-architecture" tabindex="-1">3. Application architecture <a class="header-anchor" href="#_3-application-architecture" aria-label="Permalink to &quot;3. Application architecture&quot;">​</a></h2><ul><li>Follow the original Lego DnD layout architecture strictly.</li><li>Connect Editor mode to the actual starterkit layout editor, including its palette, element tree, properties, and module/layout editing.</li><li>Disable Editor mode in production builds, including its underlying activation path.</li><li>Implement the schedule and route map as independent Baseplate modules.</li><li>Implement the bus context menu and bus-stops dialog as separate independent modules.</li><li>Share transit entities, selection, and interaction requests without coupling feature modules to one another or to the application shell.</li><li>Reuse shared table behavior for the schedule, stops dialog, and design-system examples.</li><li>Preserve independent module mount/unmount behavior and clean up roots, subscriptions, timers, and overlays.</li></ul><h2 id="_4-window-layout-and-responsiveness" tabindex="-1">4. Window layout and responsiveness <a class="header-anchor" href="#_4-window-layout-and-responsiveness" aria-label="Permalink to &quot;4. Window layout and responsiveness&quot;">​</a></h2><ul><li>Fill 100% of the browser window height.</li><li>Start with a 25% schedule / 75% map split.</li><li>Allow resizing between 25% and 75% schedule width.</li><li>Support pointer and keyboard pane resizing.</li><li>Keep table and map usable as their available space changes.</li><li>Keep the dashboard three-dot menu visible, including on narrow screens and in development mode.</li><li>Make the design-system documentation scroll correctly within the application viewport.</li><li>Keep the application-header component preview at its intended height rather than stretching across the full preview.</li></ul><h2 id="_5-bus-schedule-and-gantt" tabindex="-1">5. Bus schedule and Gantt <a class="header-anchor" href="#_5-bus-schedule-and-gantt" aria-label="Permalink to &quot;5. Bus schedule and Gantt&quot;">​</a></h2><ul><li>Provide demo buses, routes, and stops; the initial dataset contains five buses/routes and 25 stops.</li><li>Render the Gantt timeline as a column within the bus schedule table.</li><li>Include bus identity, route information, stop count, and timeline columns.</li><li>Provide only 1-, 2-, and 3-hour time windows, with 2 hours selected initially.</li><li>Keep current time at 20% of the displayed domain, leaving 80% for future time.</li><li>Update time-dependent presentation live and catch up after focus or visibility changes.</li><li>Make individual columns resizable through separators between adjacent headers.</li><li>Support pointer and keyboard column resizing.</li><li>Preserve neighboring columns&#39; combined width and minimum sizes; let the timeline fill the remaining table width.</li><li>Reuse the same resizable table implementation in the stops dialog.</li></ul><h2 id="_6-selection-and-row-states" tabindex="-1">6. Selection and row states <a class="header-anchor" href="#_6-selection-and-row-states" aria-label="Permalink to &quot;6. Selection and row states&quot;">​</a></h2><ul><li>Start with no selected bus.</li><li>Show a logical prompt when unselected: “Select a bus in the schedule to highlight its route and view its progress.”</li><li>Selecting a schedule row highlights its corresponding map route and updates the selected-bus details.</li><li>Activating the selected row again clears selection.</li><li>Support selection and clearing through pointer interaction and Enter/Space.</li><li>Opening a row&#39;s context menu selects that bus.</li><li>Preserve selection across independent module remounts.</li><li>Match selected Gantt row backgrounds to selected table-cell backgrounds.</li><li>Match hovered Gantt row backgrounds to hovered table-cell backgrounds.</li><li>Give selected rows a 2px outline on all four sides; an inset box shadow is acceptable.</li><li>Use the same outline for hover with reduced opacity.</li><li>Preserve existing background colors when adding outlines.</li><li>Keep the selected outline opaque when a selected row is hovered.</li></ul><h2 id="_7-schedule-headings-and-selected-bus-details" tabindex="-1">7. Schedule headings and selected-bus details <a class="header-anchor" href="#_7-schedule-headings-and-selected-bus-details" aria-label="Permalink to &quot;7. Schedule headings and selected-bus details&quot;">​</a></h2><ul><li>Keep the schedule category and title compact and inline, with quiet vertical border dividers between related header groups.</li><li>Consult Open-DS MCP guidance for layout and header decisions.</li><li>Render the map without a section header.</li><li>Render selected-bus details between the time-window toolbar and the table.</li><li>Include the bus identity and the applicable state: <ul><li>Departure countdown before departure.</li><li>“Estimated location from schedule” while running.</li><li>Trip-completed status after arrival.</li></ul></li><li>Explain the faded route with “Faded route: traveled.”</li><li>Replace selected-bus details with the selection prompt when no row is selected.</li><li>Preserve access to full status text when narrow layouts truncate it.</li></ul><h2 id="_8-geographic-map" tabindex="-1">8. Geographic map <a class="header-anchor" href="#_8-geographic-map" aria-label="Permalink to &quot;8. Geographic map&quot;">​</a></h2><ul><li>Display demo routes and their stops using Lego OpenLayers.</li><li>Provide a Home control that fits all routes.</li><li>Provide a Selected bus control that fits only the selected bus&#39;s route.</li><li>Make Selected bus unavailable when no bus is selected.</li><li>Fit route extents with 10% viewport padding on every edge.</li><li>Split each route at its estimated current bus position: <ul><li>Render traveled geometry with reduced opacity.</li><li>Render the remaining route at full opacity.</li></ul></li><li>Render selected routes with two ordered layers: a contrasting outline beneath the colored route.</li><li>Estimate bus locations from scheduled stop times rather than GPS.</li><li>Show location indicators for all applicable buses and emphasize the selected bus.</li><li>Before departure, keep the marker at the first stop and show a live departure countdown.</li><li>After completion, fade the entire route and hide its bus marker.</li><li>Match route colors, markers, and Gantt indicators to the active theme while preserving category identity.</li><li>Add missing theme colors needed for consistent schedule/map presentation.</li></ul><h2 id="_9-context-menu-and-bus-stops-dialog" tabindex="-1">9. Context menu and bus-stops dialog <a class="header-anchor" href="#_9-context-menu-and-bus-stops-dialog" aria-label="Permalink to &quot;9. Context menu and bus-stops dialog&quot;">​</a></h2><ul><li>Use Floating UI React for bus-row context menus.</li><li>Support pointer and keyboard context-menu access.</li><li>Provide an action that opens the selected bus&#39;s stops.</li><li>Reuse the starterkit draggable dialog layout.</li><li>Show stop details, scheduled arrival times, and live arrival countdowns.</li><li>Use the shared table with resizable columns.</li><li>Preserve accessible naming, keyboard interaction, dismissal, focus containment, and focus restoration.</li></ul><h2 id="_10-design-system-and-styling" tabindex="-1">10. Design system and styling <a class="header-anchor" href="#_10-design-system-and-styling" aria-label="Permalink to &quot;10. Design system and styling&quot;">​</a></h2><ul><li>Convert project-owned styles to CSS Modules.</li><li>Use component-owned styling inspired by Enduring CSS.</li><li>Keep every styled dashboard element in the design-system package.</li><li>Extract reusable components rather than duplicating presentation or behavior.</li><li>Adapt Open-DS Dense data decisions and tokens to the existing CSS Modules architecture rather than replacing it with the stock upstream component stack.</li><li>Use a compact, minimal monochrome design with clearer spacing and hierarchy throughout the dashboard, application header, menus, and stops dialog.</li><li>Retain distinguishable route-category colors.</li><li>Complete the reusable components actually used by Bus Map, not the entire upstream catalog.</li><li>Fix theme-preview background painting outside rounded panel corners.</li></ul><h2 id="_11-themes-and-branding" tabindex="-1">11. Themes and branding <a class="header-anchor" href="#_11-themes-and-branding" aria-label="Permalink to &quot;11. Themes and branding&quot;">​</a></h2><ul><li>Support and document all six themes: <ol><li>Monochrome Light</li><li>Monochrome Dark</li><li>Gradianto Nature Green</li><li>Gradianto Dark Fuchsia</li><li>Gradianto Deep Ocean</li><li>Gradianto Midnight Blue</li></ol></li><li>Put the monochrome options first in the theme dropdown.</li><li>With no saved choice, match the system light/dark preference and react to system changes.</li><li>Persist an explicit theme choice.</li><li>Apply themes consistently across independent modules, editor surfaces, menus, dialogs, Gantt rendering, and map presentation.</li><li>Replace Lego branding with the Bus Map bus logo, including the favicon.</li><li>Make the startup/preload bus icon and favicon match the active theme.</li><li>Fix development loading of the early document-branding module.</li><li>Validate theme colors against the Open-DS MCP server.</li></ul><h2 id="_12-design-system-reference" tabindex="-1">12. Design-system reference <a class="header-anchor" href="#_12-design-system-reference" aria-label="Permalink to &quot;12. Design-system reference&quot;">​</a></h2><ul><li>Provide a local, minimal design-system reference/showcase.</li><li>Link it from the dashboard header&#39;s three-dot menu.</li><li>Show reusable components before the theme gallery.</li><li>Document all six themes and their relevant component states.</li><li>Include the shared table with working resizable columns.</li><li>Preserve deployment-relative navigation between the dashboard and reference.</li><li>Keep the reference scrollable and its previews correctly sized.</li></ul><h2 id="_13-open-ds-integration-and-updates" tabindex="-1">13. Open-DS integration and updates <a class="header-anchor" href="#_13-open-ds-integration-and-updates" aria-label="Permalink to &quot;13. Open-DS integration and updates&quot;">​</a></h2><ul><li>Consult the local Open-DS MCP server for scheme selection, component guidance, tokens, layout best practices, and validation.</li><li>Update the local server from <a href="https://github.com/3dyonic/Open-DS" target="_blank" rel="noreferrer">Open-DS</a>, restart it, and rerun validation.</li><li>Fix incompatibilities introduced by upstream updates.</li><li>Keep the upstream Open-DS brand website stopped; retain the MCP server when needed.</li></ul><h2 id="_14-github-repositories-and-publication" tabindex="-1">14. GitHub repositories and publication <a class="header-anchor" href="#_14-github-repositories-and-publication" aria-label="Permalink to &quot;14. GitHub repositories and publication&quot;">​</a></h2><ul><li>Create a private source repository named <code>bus-map</code>.</li><li>Use the currently authenticated GitHub CLI account.</li><li>Maintain the existing <a href="https://github.com/airafa/bus-map/pull/1" target="_blank" rel="noreferrer">PR #1</a> for the accumulated application changes.</li><li>Commit and push changes when requested, updating that existing PR rather than creating duplicate delivery work.</li><li>Create and configure a separate public repository for production distribution only.</li><li>Keep application source and registry credentials private.</li><li>Publish only the minified production build and required runtime assets, without source maps.</li><li>Configure and update <a href="https://airafa.github.io/bus-map-pages/" target="_blank" rel="noreferrer">GitHub Pages</a>.</li><li>Add search-engine indexing opt-outs and robot directives. These are voluntary crawler controls, not access protection.</li><li>When delivery is requested, rebuild, publish, and verify the actual live deployment.</li></ul><h2 id="_15-validation-and-acceptance" tabindex="-1">15. Validation and acceptance <a class="header-anchor" href="#_15-validation-and-acceptance" aria-label="Permalink to &quot;15. Validation and acceptance&quot;">​</a></h2><ul><li>Verify Yarn development startup and production builds.</li><li>Run relevant existing tests and strict TypeScript checks.</li><li>Leave runnable regression coverage for non-trivial behavior.</li><li>Validate actual browser behavior for layout, resizing, selection, menus, dialogs, themes, and map controls.</li><li>Validate Open-DS decisions and theme colors through the local MCP server.</li><li>Verify production cannot activate Editor mode.</li><li>Verify the final map has no section header, the schedule details sit between toolbar and table, and the initial state has no selected row.</li><li>Verify the existing PR contains the requested changes and the published Pages deployment serves the corresponding build.</li></ul>',32)])])}const m=i(n,[["render",o]]);export{p as __pageData,m as default};
